do $$declare student uuid:='00000005-0000-4000-8000-000000000000'; source uuid; slot uuid; fixed uuid; other uuid; result jsonb; before_time text; count_before bigint; body jsonb;
begin
  select (value->>'id')::uuid into source from test.records where name='source_attempt';
  select (value->>'id')::uuid into slot from test.records where name='elective_slot';
  select (value->>'id')::uuid into fixed from test.records where name='slot';
  body:=jsonb_build_object('attempt_id',source,'curriculum_term_course_id',slot,'justification','Test mapping');
  perform test.login(8);
  perform test.expect('PT403','createElectiveMapping',jsonb_build_object('student_id',student),body);
  perform test.login(1);
  perform test.expect('PT403','createElectiveMapping',jsonb_build_object('student_id',student),body);
  perform test.login(4);
  perform test.expect('PT404','createElectiveMapping',jsonb_build_object('student_id',student),body||'{"attempt_id":"ffffffff-0000-4000-8000-000000000000"}');
  perform test.expect('PT409','createElectiveMapping',jsonb_build_object('student_id',student),body||jsonb_build_object('curriculum_term_course_id',fixed));
  result:=test.call('createElectiveMapping',jsonb_build_object('student_id',student),body);
  perform test.assert((result->>'units_credited')::numeric=3,'server-derived source units');
  perform test.assert(not result ? 'justification','private justification exposed');
  before_time:=result->>'updated_at';
  perform test.expect('PT409','createElectiveMapping',jsonb_build_object('student_id',student),body);
  result:=test.call('updateElectiveMapping',jsonb_build_object('student_id',student,'decision_id',result->>'id'),body||jsonb_build_object('expected_updated_at',before_time));
  perform test.expect('PT409','revokeElectiveMapping',jsonb_build_object('student_id',student,'decision_id',result->>'id'),jsonb_build_object('reason','Stale','expected_updated_at',before_time));
  result:=test.call('revokeElectiveMapping',jsonb_build_object('student_id',student,'decision_id',result->>'id'),jsonb_build_object('reason','Test revoke','expected_updated_at',result->>'updated_at'));
  perform test.assert(result->>'revoked_at' is not null,'soft revoke mapping');
  body:=jsonb_build_object('attempt_id',source,'destination_curriculum_term_course_id',fixed,'decision_type','transfer_equivalency','justification','Test equivalency');
  result:=test.call('createEquivalencyDecision',jsonb_build_object('student_id',student),body);
  perform test.expect('PT409','createElectiveMapping',jsonb_build_object('student_id',student),jsonb_build_object('attempt_id',source,'curriculum_term_course_id',slot,'justification','Duplicate source'));
  result:=test.call('updateEquivalencyDecision',jsonb_build_object('student_id',student,'decision_id',result->>'id'),body||jsonb_build_object('expected_updated_at',result->>'updated_at'));
  result:=test.call('revokeEquivalencyDecision',jsonb_build_object('student_id',student,'decision_id',result->>'id'),jsonb_build_object('reason','Test revoke','expected_updated_at',result->>'updated_at'));
  perform test.assert((select count(*)>=4 from saais_private.credit_history where student_id=student),'effective-dated credit history');
  perform test.login(2);
  body:=jsonb_build_object('entry_type','transferee','origin_school',' Test  School ','original_course_code',' SRC 101 ','original_course_title','Prior Subject','units',3,'grade','2.00','destination_curriculum_term_course_id',slot,'reason','Passed prior course');
  result:=test.call('createOutsideCredit',jsonb_build_object('student_id',student),body);
  perform test.expect('PT409','createOutsideCredit',jsonb_build_object('student_id',student),body||jsonb_build_object('origin_school','test school','original_course_code','src 101','destination_curriculum_term_course_id',fixed));
  perform test.login(6);
  perform test.expect('PT403','revokeOutsideCredit',jsonb_build_object('student_id',student,'credit_id',result->>'id'),jsonb_build_object('reason','Out of scope','expected_updated_at',result->>'updated_at'));
  perform test.login(2);
  result:=test.call('revokeOutsideCredit',jsonb_build_object('student_id',student,'credit_id',result->>'id'),jsonb_build_object('reason','Test revoke','expected_updated_at',result->>'updated_at'));
  perform test.assert(result->>'revoked_at' is not null,'outside soft revoke');
  perform test.assert((select final_grade=2 from public.attempt where id=source),'credits changed attempt grade');
  perform test.assert((select revision>=8 from saais_private.cache_invalidation where student_id=student),'cache revision invalidation');
end$$;
